{"implementation":"def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    edges = []
    for u, v, d in distances:
        w = max(core_distance[u], core_distance[v], d)
        if u < v:
            edges.append((u, v, w))
        else:
            edges.append((v, u, w))

    edges.sort(key=lambda e: (e[2], e[0], e[1]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Disconnected graph")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"}
